 "content": "def transform(grid):
    """Restore masked cells from the grid's main-diagonal reflection."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    unresolved = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                reflected = grid[c][r] if c < h and r < w else 6
                if reflected != 6:
                    out[r][c] = reflected
                else:
                    unresolved.append((r, c))
    # A mask can cover a point on the reflection axis itself. Infer that
    # diagonal value from the most similar fully visible diagonal neighborhood.
    for r, c in unresolved:
        candidates = []
        for k in range(min(h, w)):
            if grid[k][k] == 6:
                continue
            matches = 0
            compared = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    kr, kc = k + dr, k + dc
                    if 0 <= rr < h and 0 <= cc < w and 0 <= kr < h and 0 <= kc < w:
                        a, b = grid[rr][cc], grid[kr][kc]
                        if a != 6 and b != 6:
                            compared += 1
                            matches += (a == b)
            candidates.append((matches, compared, grid[k][k]))
        if candidates:
            best = max(candidates, key=lambda item: (item[0] / item[1] if item[1] else 0, item[0], item[1]))
            out[r][c] = best[2]
    return out

