 "content": "def transform(grid):
    """Recover 6-masked cells using the grid's transpose and row-repeat symmetries."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6 or (r, c) in seen:
                continue
            # A hidden cell can be linked to other cells by diagonal reflection
            # and by the repeated horizontal row pattern (row indices sum to 31).
            stack = [(r, c)]
            component = []
            known = []
            while stack:
                rr, cc = stack.pop()
                if (rr, cc) in seen:
                    continue
                seen.add((rr, cc))
                if grid[rr][cc] != 6:
                    known.append(grid[rr][cc])
                    continue
                component.append((rr, cc))
                neighbors = [(cc, rr), (31 - rr, cc)]
                for nr, nc in neighbors:
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                        stack.append((nr, nc))
            if known:
                value = known[0]
                for rr, cc in component:
                    out[rr][cc] = value
    return out

